import subprocess
import sys


def test_condefects_0():
    proc = subprocess.run(
        [sys.executable, "buggy.py"],
        input='3\n25\n148\n998244353\n',
        capture_output=True,
        text=True,
        timeout=10,
    )
    expected = '27\n173\n2506230721\n'
    actual = proc.stdout.strip()
    assert actual == expected.strip(), (
        f"Expected {expected.strip()!r}, got {actual!r}"
    )


